Here is a complete, self-contained 3D first-person shooter game built with Three.js. It features movement, shooting, enemy AI that chases you, and a scoring system.

<!-- path: threejs_game.html -->
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Abyx 3D Shooter</title>
    <style>
        body { margin: 0; overflow: hidden; font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; user-select: none; }
        #ui-layer { position: absolute; top: 0; left: 0; width: 100%; height: 100%; pointer-events: none; display: flex; flex-direction: column; justify-content: space-between; padding: 20px; box-sizing: border-box; }
        #score-board { font-size: 32px; color: #fff; text-shadow: 2px 2px 4px #000; font-weight: bold; }
        #health-bar-container { width: 300px; height: 20px; background: rgba(50, 50, 50, 0.8); border: 2px solid #fff; margin-top: 10px; transform: skewX(-20deg); }
        #health-fill { width: 100%; height: 100%; background: linear-gradient(90deg, #f00, #ff4500); transition: width 0.1s; }
        #crosshair { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); width: 20px; height: 20px; border: 2px solid rgba(255, 255, 255, 0.8); border-radius: 50%; }
        #crosshair::after { content: ''; position: absolute; top: 9px; left: 9px; width: 2px; height: 2px; background: red; border-radius: 50%; opacity: 0.8; }
        #instructions { position: absolute; top: 10px; right: 10px; color: #fff; text-align: right; font-size: 14px; text-shadow: 1px 1px 2px #000; pointer-events: none; }
        #game-over { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); background: rgba(0, 0, 0, 0.9); padding: 40px; text-align: center; color: white; border-radius: 10px; display: none; pointer-events: auto; box-shadow: 0 0 50px rgba(255, 0, 0, 0.5); }
        #game-over h1 { margin: 0 0 10px; color: #ff4444; font-size: 48px; text-transform: uppercase; }
        #final-score { font-size: 24px; margin-bottom: 20px; }
        button { background: #ff4500; border: none; padding: 15px 30px; color: white; font-size: 20px; cursor: pointer; border-radius: 5px; transition: transform 0.2s, box-shadow 0.2s; }
        button:hover { background: #ff6a00; transform: scale(1.05); box-shadow: 0 0 15px #ff4500; }
        canvas { display: block; }
    </style>
</head>
<body>

<div id="ui-layer">
    <div style="display:flex; flex-direction:column;">
        <div id="score-board">SCORE: 0</div>
        <div id="health-bar-container"><div id="health-fill"></div></div>
    </div>
    <div id="instructions">WASD to Move | SPACE to Jump<br>MCLICK to Shoot | ESC to Pause</div>
    <div id="crosshair"></div>
    <div id="game-over">
        <h1>Game Over</h1>
        <div id="final-score">Score: 0</div>
        <button onclick="restartGame()">RESTART MISSION</button>
    </div>
</div>

<!-- Import Three.js as a module -->
<script type="module">
    import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';
    import { PointerLockControls } from 'https://unpkg.com/three@0.160.0/examples/jsm/controls/PointerLockControls.js';

    // --- Game Constants & State ---
    const PLAYER_SPEED = 15.0;
    const PLAYER_JUMP_FORCE = 12.0;
    const GRAVITY = 30.0;
    const ENEMY_SPEED = 8.0;
    const ENEMY_SPAWN_RATE = 2000; // ms
    let lastTime = performance.now();

    let gameState = {
        score: 0,
        health: 100,
        isRunning: true,
        enemies: [],
        bullets: [],
        particles: [],
        lastShot: 0,
        spawnTimer: 0
    };

    // --- Scene Setup ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x111823); // Dark grey/blue
    scene.fog = new THREE.FogExp2(0x111823, 0.02);

    const camera = scene.camera;
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    document.body.appendChild(renderer.domElement);

    // --- Lighting ---
    const ambientLight = new THREE.AmbientLight(0x404040, 1.5);
    scene.add(ambientLight);

    const dirLight = new THREE.DirectionalLight(0xffffff, 1);
    dirLight.position.set(10, 20, 10);
    scene.add(dirLight);

    // --- Controls ---
    const controls = new PointerLockControls(camera, document.body);

    // UI Elements
    const scoreEl = document.getElementById('score-board');
    const healthFillEl = document.getElementById('health-fill');
    const gameOverEl = document.getElementById('game-over');
    const finalScoreEl = document.getElementById('final-score');

    // --- Input Handling ---
    const moveState = { forward: false, backward: false, left: false, right: false, jump: false };

    document.addEventListener('keydown', (event) => {
        switch(event.code) {
            case 'KeyW': moveState.forward = true; break;
            case 'KeyS': moveState.backward = true; break;
            case 'KeyA': moveState.left = true; break;
            case 'KeyD': moveState.right = true; break;
            case 'Space': if(camera.position.y <= 1.6) camera.velocity.y = PLAYER_JUMP_FORCE; else if(!moveState.jump) { // Simple jump buffer check could go here, simplified for now
                camera.velocity.y = PLAYER_JUMP_FORCE;
                moveState.jump = true; 
            } break;
        }
    });

    document.addEventListener('keyup', (event) => {
        switch(event.code) {
            case 'KeyW': moveState.forward = false; break;
            case 'KeyS': moveState.backward = false; break;
            case 'KeyA': moveState.left = false; break;
            case 'KeyD': moveState.right = false; break;
            case 'Space': moveState.jump = false; break;
        }
    });

    document.addEventListener('mousedown', () => {
        if (gameState.isRunning) shoot();
    });

    // --- World Objects ---

    // Floor
    const floorGeometry = new THREE.PlaneGeometry(100, 100);
    const floorMaterial = new THREE.MeshStandardMaterial({ 
        color: 0x2a3b55, 
        roughness: 0.8,
        metalness: 0.2
    });
    const floor = new THREE.Mesh(floorGeometry, floorMaterial);
    floor.rotation.x = -Math.PI / 2;
    scene.add(floor);

    // Grid helper for visual depth
    const gridHelper = new THREE.GridHelper(100, 100, 0x445566, 0x2a3b55);
    scene.add(gridHelper);

    // Player Model (Simple Capsule-like representation)
    const playerGroup = new THREE.Group();

    // Torso
    const torsoGeo = new THREE.BoxGeometry(1.8, 1.8, 0.8);
    const torsoMat = new THREE.MeshStandardMaterial({ color: 0x3b4d61 });
    const torso = new THREE.Mesh(torsoGeo, torsoMat);
    torso.position.y = 2.4; // Eye level approx
    playerGroup.add(torso);

    // Head
    const headGeo = new THREE.BoxGeometry(1.2, 1.0, 1.2);
    const headMat = new THREE.MeshStandardMaterial({ color: 0xffccaa });
    const head = new THREE.Mesh(headGeo, headMat);
    head.position.y = 3.5;
    playerGroup.add(head);

    // Gun (Simple Box)
    const gunGeo = new THREE.BoxGeometry(0.4, 0.6, 2.5);
    const gunMat = new THREE.MeshStandardMaterial({ color: 0x1a1a1a });
    const gun = new THREE.Mesh(gunGeo, gunMat);
    gun.position.set(1.2, -0.3, -1.8); // Relative to torso
    playerGroup.add(gun);

    scene.add(playerGroup);

    // Player Physics State
    camera.velocity = new THREE.Vector3();
    const velocity = new THREE.Vector3(); // For simple gravity/jump handling if needed
    let canJump = true;
    camera.position.y = 1.6;

    // --- Game Logic Functions ---

    function shoot() {
        const now = performance.now();
        if (now - gameState.lastShot < 200) return; // Fire rate limit
        gameState.lastShot = now;

        // Recoil animation
        gun.rotation.x += 0.1;

        // Create Bullet
        const bulletGeo = new THREE.SphereGeometry(0.2, 8, 8);
        const bulletMat = new THREE.MeshBasicMaterial({ color: 0xffffaa });
        const bullet = new THREE.Mesh(bulletGeo, bulletMat);

        // Position at gun tip roughly
        bullet.position.copy(playerGroup.position);
        bullet.quaternion.copy(camera.quaternion);
        // Offset slightly forward from camera to align with gun model
        bullet.translateZ(2.5); 

        scene.add(bullet);
        gameState.bullets.push({ mesh: bullet, velocity: new THREE.Vector3() });

        // Calculate direction
        const dir = new THREE.Vector3();
        playerGroup.getWorldDirection(dir);

        // Add a bit of spread or keep precise? Let's keep precise for now.
        bullet.velocity.copy(dir).normalize().multiplyScalar(50); 

        // Flash effect on gun
        const flashLight = new THREE.PointLight(0xffffaa, 2, 3);
        flashLight.position.set(1.2, -0.3, -1.8);
        playerGroup.add(flashLight);
        setTimeout(() => { if(playerGroup.children.length > 4) playerGroup.remove(flashLight); }, 50);
    }

    function spawnEnemy() {
        // Random position on the floor circle around player but far away
        const angle = Math.random() * Math.PI * 2;
        const radius = 30 + Math.random() * 20;
        const x = camera.position.x + Math.cos(angle) * radius;
        const z = camera.position.z + Math.sin(angle) * radius;

        // Enemy Geometry (Red Cube)
        const enemyGeo = new THREE.BoxGeometry(1.5, 3, 1.5);
        const enemyMat = new THREE.MeshStandardMaterial({ color: 0xff2a2a });
        const enemy = new THREE.Mesh(enemyGeo, enemyMat);

        enemy.position.set(x, 1.5, z); // 1.5 is half height

        scene.add(enemy);
        gameState.enemies.push({ mesh: enemy, health: 3 });
    }

    function createExplosion(position) {
        const particleCount = 8;
        for (let i = 0; i < particleCount; i++) {
            const geo = new THREE.BoxGeometry(0.5, 0.5, 0.5);
            const mat = new THREE.MeshBasicMaterial({ color: 0xffaa00 });
            const mesh = new THREE.Mesh(geo, mat);

            mesh.position.copy(position);

            // Random velocity
            const vel = new THREE.Vector3(
                (Math.random() - 0.5) * 10,
                Math.random() * 10 + 2,
                (Math.random() - 0.5) * 10
            );

            scene.add(mesh);
            gameState.particles.push({ mesh: mesh, velocity: vel, life: 1.0 });
        }
    }

    function updateBullets() {
        for (let i = gameState.bullets.length - 1; i >= 0; i--) {
            const b = gameState.bullets[i];
            b.mesh.position.add(b.velocity);

            // Distance check against enemies
            let hit = false;
            for (let j = gameState.enemies.length - 1; j >= 0; j--) {
                const e = gameState.enemies[j];
                if (b.mesh.position.distanceTo(e.mesh.position) < 2.5) {
                    // Hit!
                    e.health--;
                    createExplosion(b.mesh.position); // Small hit effect

                    // Knockback bullet
                    b.velocity.multiplyScalar(-1).multiplyScalar(0.8); 
                    hit = true;

                    if (e.health <= 0) {
                        createExplosion(e.mesh.position); // Big death effect
                        scene.remove(e.mesh);
                        gameState.enemies.splice(j, 1);

                        // Score update
                        gameState.score += 100;
                        scoreEl.innerText = "SCORE: " + gameState.score;

                        // Respawn bullet if it was consumed? Or just remove. Let's keep it simple: remove on hit or out of bounds.
                        if (hit) {
                             scene.remove(b.mesh);
                             gameState.bullets.splice(i, 1);
                             break; 
                        }
                    }
                }
            }

            // Remove if far away or hit
            if (!hit && b.mesh.position.distanceTo(camera.position) > 60) {
                 scene.remove(b.mesh);
                 gameState.bullets.splice(i, 1);
            }
        }
    }

    function updateEnemies() {
        const time = performance.now();

        // Spawning
        if (time - gameState.spawnTimer > ENEMY_SPAWN_RATE) {
            spawnEnemy();
            gameState.spawnTimer = time;

            // Make it harder over time
            if (ENEMY_SPAWN_RATE > 500) ENEMY_SPAWN_RATE -= 100;
        }

        // AI Movement
        for (let i = 0; i < gameState.enemies.length; i++) {
            const e = gameState.enemies[i];

            const direction = new THREE.Vector3().subVectors(camera.position, e.mesh.position).normalize();
            e.mesh.lookAt(camera.position);
            e.mesh.translateZ(ENEMY_SPEED);

            // Simple collision with player (Instant death)
            if (e.mesh.position.distanceTo(camera.position) < 2.0) {
                takeDamage(25); // High damage per frame
                createExplosion(e.mesh.position);
                scene.remove(e.mesh);
                gameState.enemies.splice(i, 1);
                i--;

                // Screen shake effect (simple camera offset could go here)
            }
        }
    }

    function takeDamage(amount) {
        if (!gameState.isRunning) return;

        gameState.health -= amount;
        healthFillEl.style.width = gameState.health + '%';

        // Flash screen red
        const flash = document.createElement('div');
        flash.style.cssText = "position:absolute;top:0;left:0;width:100%;height:100%;background:red;opacity:0.3;pointer-events:none;z-index:999;";
        document.body.appendChild(flash);
        setTimeout(() => { if(document.body.contains(flash)) flash.remove(); }, 50);

        if (gameState.health <= 0) {
            endGame();
        }
    }

    function updateParticles() {
        for (let i = gameState.particles.length - 1; i >= 0; i--) {
            const p = gameState.particles[i];
            p.mesh.position.add(p.velocity);
            p.mesh.scale.multiplyScalar(0.95); // Shrink

            if (p.life < 0) {
                scene.remove(p.mesh);
                gameState.particles.splice(i, 1);
            } else {
                p.life -= 0.1;
            }
        }
    }

    function updatePlayer() {
        // Movement vector based on camera direction (ignoring Y)
        const delta = 50 / 60; // Time step approx

        if (controls.isLocked) {
            const forward = new THREE.Vector3();
            const right = new THREE.Vector3();

            forward.copy(camera.up).cross(camera.getWorldDirection(new THREE.Vector3())).normalize();
            right.cross(forward, new THREE.Vector3());

            // Apply inputs
            velocity.x = 0;
            velocity.z = 0;

            if (moveState.forward) {
                forward.multiplyScalar(-PLAYER_SPEED);
                velocity.add(forward);
            }
            if (moveState.backward) {
                forward.multiplyScalar(PLAYER_SPEED);
                velocity.add(forward);
            }
            if (moveState.left) {
                right.multiplyScalar(-PLAYER_SPEED);
                velocity.add(right);
            }
            if (moveState.right) {
                right.multiplyScalar(PLAYER_SPEED);
                velocity.add(right);
            }

            // Apply movement to player position
            playerGroup.position.x += velocity.x * delta;
            playerGroup.position.z += velocity.z * delta;

            // Friction
            velocity.multiplyScalar(0.95);
        }

        // Gravity
        camera.position.y -= (camera.velocity.y - 2) * delta; // Simple gravity accel
        if (camera.position.y < 1.6) {
            camera.position.y = 1.6;
            camera.velocity.y = 0;
        }

        // Gun sway/recoil recovery
        gun.rotation.x -= (gun.rotation.x - 0.5) * 0.2; 
    }

    function endGame() {
        gameState.isRunning = false;
        controls.unlock();
        gameOverEl.style.display = 'block';
        finalScoreEl.innerText = "Final Score: " + gameState.score;

        // Play sound (optional, but we can simulate or add later)
        // const audioCtx = new AudioContext(); ...
    }

    window.restartGame = function() {
        // Reset state
        gameState.score = 0;
        gameState.health = 100;
        gameState.enemies.forEach(e => scene.remove(e.mesh));
        gameState.bullets.forEach(b => scene.remove(b.mesh));
        gameState.particles.forEach(p => scene.remove(p.mesh));

        scoreEl.innerText = "SCORE: 0";
        healthFillEl.style.width = '100%';
        gameOverEl.style.display = 'none';

        playerGroup.position.set(0, 1.6, 0);

        camera.velocity.set(0, 20, 0); // Jump to start
        gameState.isRunning = true;
        controls.lock();
    };

    function animate() {
        requestAnimationFrame(animate);

        const time = performance.now();
        const delta = (time - lastTime) / 1000 || 0;
        lastTime = time;

        if (gameState.isRunning) {
            updatePlayer(delta);
            updateBullets();
            updateEnemies();
            updateParticles();

            // Smooth camera velocity for jump physics
            camera.velocity.y -= GRAVITY * delta;
        }

        renderer.render(scene, camera);
    }

    // Handle window resize
    window.addEventListener('resize', () => {
        renderer.setSize(window.innerWidth, window.innerHeight);
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
    });

    animate();

</script>
</body>
</html>
